export class BVec4 {
	// Fields are `declare`d instead of parameter properties so no class fields
	// are emitted (see the note in `Vec2`).
	/** The `x` element. */
	declare x: boolean;
	/** The `y` element. */
	declare y: boolean;
	/** The `z` element. */
	declare z: boolean;
	/** The `w` element. */
	declare w: boolean;

	constructor(x: boolean, y: boolean, z: boolean, w: boolean) {
		this.x = x;
		this.y = y;
		this.z = z;
		this.w = w;
	}

	/** All false. (false, false..) */
	static get FALSE() {
		return new BVec4(false, false, false, false);
	}

	/** All true. (true, true..) */
	static get TRUE() {
		return new BVec4(true, true, true, true);
	}

	/** Creates a vector with all elements set to v. */
	static splat(v: boolean): BVec4 {
		return new BVec4(v, v, v, v);
	}

	/**
	 * Returns a bitmask with the lowest 4 bits set from the elements of BVec4.
	 * A true element results in a 1 bit and a false element in a 0 bit. Element x goes into the first lowest bit, element y into the second, etc.
	 */
	bitmask(): number {
		return (
			(this.x ? 1 : 0) | (this.y ? 2 : 0) | (this.z ? 4 : 0) | (this.w ? 8 : 0)
		);
	}

	/** Returns true if any of the elements are true, false otherwise. */
	any(): boolean {
		return this.x || this.y || this.z || this.w;
	}

	/** Returns true if all the elements are true, false otherwise. */
	all(): boolean {
		return this.x && this.y && this.z && this.w;
	}

	/** Tests the value at index. */
	test(index: 0 | 1 | 2 | 3): boolean | undefined {
		switch (index) {
			case 0:
				return this.x;
			case 1:
				return this.y;
			case 2:
				return this.z;
			case 3:
				return this.w;
			default:
				return undefined;
		}
	}

	/** Sets the element at index. */
	set(index: 0 | 1 | 2 | 3, value: boolean): void {
		switch (index) {
			case 0: {
				this.x = value;
				break;
			}
			case 1: {
				this.y = value;
				break;
			}
			case 2: {
				this.z = value;
				break;
			}
			case 3: {
				this.w = value;
				break;
			}
			default:
				break;
		}
	}

	/** Performs the & operation. */
	bitand(rhs: BVec4): BVec4 {
		return new BVec4(
			this.x && rhs.x,
			this.y && rhs.y,
			this.z && rhs.z,
			this.w && rhs.w,
		);
	}

	/** Performs the | operation. */
	bitor(rhs: BVec4): BVec4 {
		return new BVec4(
			this.x || rhs.x,
			this.y || rhs.y,
			this.z || rhs.z,
			this.w || rhs.w,
		);
	}

	/** Performs the ^ operation. */
	bitxor(rhs: BVec4): BVec4 {
		return new BVec4(
			this.x !== rhs.x,
			this.y !== rhs.y,
			this.z !== rhs.z,
			this.w !== rhs.w,
		);
	}

	/** Returns the negation. */
	not(): BVec4 {
		return new BVec4(!this.x, !this.y, !this.z, !this.w);
	}

	/** This method tests for self and other values to be equal, and is used by ==. */
	eq(rhs: BVec4 | boolean): boolean {
		if (typeof rhs === "boolean") {
			return (
				this.x === rhs && this.y === rhs && this.z === rhs && this.w === rhs
			);
		}

		return (
			this.x === rhs.x &&
			this.y === rhs.y &&
			this.z === rhs.z &&
			this.w === rhs.w
		);
	}

	/** This method tests for !=. */
	ne(rhs: BVec4 | boolean): boolean {
		if (typeof rhs === "boolean") {
			return (
				this.x !== rhs || this.y !== rhs || this.z !== rhs || this.w !== rhs
			);
		}

		return (
			this.x !== rhs.x ||
			this.y !== rhs.y ||
			this.z !== rhs.z ||
			this.w !== rhs.w
		);
	}

	/** Prints out a formatted output of the instance. */
	toString() {
		return `BVec4(${this.x}, ${this.y}, ${this.z}, ${this.w})`;
	}
}
